import { AggregateRoot, DomainError, notImplemented } from '@agentic-ddd/core';
import { AgentEntity, AgentMethod, Invariant } from '@agentic-ddd/decorators';
import { TaskCreated, TaskCompleted } from './task.events';

@AgentEntity({ description: 'Tarefa com título e ciclo de vida pendente ou concluído.', states: ['pending', 'completed'] })
@Invariant({ id: 'titulo-obrigatorio', text: 'Toda tarefa precisa de título não vazio.' })
export class Task extends AggregateRoot<string> {
  #status: 'pending' | 'completed' = 'pending';
  private constructor(id: string, readonly title: string) { super(id); }
  get status(): 'pending' | 'completed' { return this.#status; }

  @AgentMethod({ description: 'Cria uma tarefa pendente e remove espaços nas extremidades do título.', emits: [TaskCreated] })
  static create(id: string, title: string): Task {
    const normalizedTitle = title.trim();
    if (!normalizedTitle) {
      throw new DomainError('TASK_TITLE_REQUIRED', 'Toda tarefa precisa de título não vazio.');
    }
    const task = new Task(id, normalizedTitle);
    task.record(new TaskCreated({ taskId: id, title: normalizedTitle }));
    return task;







  }

  @AgentMethod({ description: 'Conclui uma tarefa pendente; repetição falha com TASK_ALREADY_COMPLETED.', transition: { from: ['pending'], to: 'completed' }, emits: [TaskCompleted] })
  complete(): void {
    return notImplemented();













  }
}

import { expect, test } from 'bun:test';
import { DomainError } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { Task } from '../domain/task';
import { TaskCreated } from '../domain/task.events';

for (const title of ['', '   ', '\t\n\r ']) {
  test(covers([
    'invariant:Task/titulo-obrigatorio',
    'method:Task.create',
    'criterion:0001/titulo-invalido',
  ], `rejeita título vazio após normalização: ${JSON.stringify(title)}`), () => {
    let failure: unknown;
    try {
      Task.create('t1', title);
    } catch (error) {
      failure = error;
    }
    expect(failure).toBeInstanceOf(DomainError);
    expect((failure as DomainError).code).toBe('TASK_TITLE_REQUIRED');
  });
}

test(covers([
  'invariant:Task/titulo-obrigatorio',
  'method:Task.create',
  'criterion:0001/criacao',
], 'cria tarefa pendente, normaliza título e registra TaskCreated'), () => {
  const task = Task.create('t1', ' \tComprar  pão\n ');

  expect(task.id).toBe('t1');
  expect(task.title).toBe('Comprar  pão');
  expect(task.status).toBe('pending');

  const events = task.pullEvents();
  expect(events).toHaveLength(1);
  expect(events[0]).toBeInstanceOf(TaskCreated);
  expect(events[0]!.name).toBe('TaskCreated');
  expect(events[0]!.payload).toEqual({ taskId: 't1', title: 'Comprar  pão' });
  expect(task.pullEvents()).toEqual([]);
});
